TEST = r'''package ls.augment.com;
import java.util.*;import android.widget.*;import android.view.*;import android.os.Handler;import java.lang.reflect.*;
public class EntryControlsTest{
 static int checks;static void check(boolean v,String why){checks++;if(!v)throw new AssertionError(why);}
 static Object field(Object o,String key)throws Exception{Field f=o.getClass().getDeclaredField(key);f.setAccessible(true);return f.get(o);}
 static class Queue implements java.util.concurrent.Executor{final ArrayDeque<Runnable>q=new ArrayDeque<>();public void execute(Runnable r){q.add(r);}void run(){while(!q.isEmpty())q.remove().run();Handler.drain();}}
 static class F{final AtomicWorkbenchSettingsActivity a=new AtomicWorkbenchSettingsActivity();final AppConfig config=new AppConfig();final Queue q=new Queue();int changes;final AtomicWorkbenchAppearanceControls c=new AtomicWorkbenchAppearanceControls(a,new UiKit(a),config,ResetWriteFence.value,q,()->changes++);ParameterSlider slider(String n)throws Exception{return(ParameterSlider)field(c,n);}void clear(){c.detach();Handler.later.clear();}}
 static void touch(SeekBar b,int action,int value){b.dispatchTouchEvent(new MotionEvent(action,value));}
 public static void main(String[]args)throws Exception{
  for(String key:List.of("triggerArea","cornerSensitivity")){F f=new F();ParameterSlider s=f.slider(key);check(s.bar.getMin()==(key.equals("triggerArea")?50:60)&&s.bar.getMax()==(key.equals("triggerArea")?120:160),"wrong slider range");check(s.bar.getProgress()==100&&f.config.saves==0,"refresh wrote configuration");touch(s.bar,0,105);touch(s.bar,2,110);check(f.q.q.isEmpty()&&s.bar.getProgress()==110,"drag saved before release");touch(s.bar,1,111);check(f.q.q.size()==1,"release did not queue one save");f.q.run();check(f.config.saves==1&&f.changes==1&&s.bar.getProgress()==111,"release save failed");f.clear();}
  for(String kind:List.of("cancel","multi","barfocus","focus","detach","rebind","reset")){F f=new F();ParameterSlider s=f.slider("triggerArea");touch(s.bar,0,105);touch(s.bar,2,115);switch(kind){case "cancel":touch(s.bar,3,115);break;case "multi":s.bar.dispatchTouchEvent(new MotionEvent(MotionEvent.ACTION_POINTER_DOWN,115,2));break;case "barfocus":s.bar.focus.onFocusChange(s.bar,false);break;case "focus":s.onWindowFocusChanged(false);break;case "detach":f.c.detach();break;case "rebind":AppConfig next=new AppConfig();next.values.put(AtomicWorkbenchConfig.TRIGGER_AREA_SCALE,"107");f.c.rebind(next,ResetWriteFence.value);break;default:ResetWriteFence.value++;}touch(s.bar,1,118);f.q.run();check(f.config.saves==0&&f.changes==0,"cancelled draft committed: "+kind);check(s.bar.getProgress()==(kind.equals("rebind")?107:100),"cancelled value not restored: "+kind);f.clear();}
  for(String kind:List.of("keyboard","accessibility")){F f=new F();ParameterSlider s=f.slider("cornerSensitivity");s.bar.set(109,true);check(f.q.q.size()==1,"native non-touch step not submitted: "+kind);f.q.run();check(f.config.saves==1&&s.bar.getProgress()==109,"native step lost");f.clear();}
  {F f=new F();ParameterSlider s=f.slider("triggerArea");f.config.success=false;touch(s.bar,0,105);touch(s.bar,1,110);f.q.run();check(f.config.saves==1&&f.changes==0&&s.bar.getProgress()==100,"failed save falsely applied");f.clear();}
  for(String kind:List.of("rebind","destroy","detach")){F f=new F();ParameterSlider s=f.slider("triggerArea");touch(s.bar,0,105);touch(s.bar,1,110);if(kind.equals("rebind"))f.c.rebind(new AppConfig(),ResetWriteFence.value);else if(kind.equals("destroy"))f.a.destroyed=true;else f.c.detach();f.q.run();check(f.changes==0&&field(f.c,"preview")==null,"stale callback affected departed controls");f.clear();}
  {F f=new F();ParameterSlider s=f.slider("triggerArea");touch(s.bar,0,105);touch(s.bar,1,120);f.q.run();android.graphics.drawable.Drawable d=(android.graphics.drawable.Drawable)field(f.c,"preview");check(d!=null,"successful area save did not preview");android.graphics.Canvas canvas=new android.graphics.Canvas();d.draw(canvas);var g=AtomicWorkbenchGesturePolicy.Geometry.create(1216,2688,3.25f,90,120,100);check(canvas.rectangles.size()==2,"preview missing a corner");float[]left=canvas.rectangles.get(0),right=canvas.rectangles.get(1);check(left[0]==0&&left[1]==g.minY&&left[2]==g.edge&&left[3]==g.maxY&&right[0]==g.width-g.edge&&right[2]==g.width,"preview differs from detector geometry");Handler.advance(1999);check(field(f.c,"preview")!=null,"preview ended before two seconds");Handler.advance(1);check(field(f.c,"preview")==null&&f.a.getWindow().getDecorView().getOverlay().values.isEmpty(),"preview did not clear at two seconds");f.clear();}
  for(String kind:List.of("layout","detach","disabled")){F f=new F();ParameterSlider s=f.slider("triggerArea");touch(s.bar,0,105);touch(s.bar,1,110);f.q.run();if(kind.equals("layout"))f.a.getWindow().getDecorView().resize();else if(kind.equals("detach"))f.c.detach();else f.c.refresh(false);check(field(f.c,"preview")==null,"preview survived invalid owner: "+kind);f.clear();}
  {UiKit ui=new UiKit(new AtomicWorkbenchSettingsActivity());List<String>values=new ArrayList<>();ParameterSlider old=new ParameterSlider(ui,EnhancementOption.integer("old","test","old","",100,50,120),"100",values::add);touch(old.bar,0,105);touch(old.bar,2,110);touch(old.bar,1,111);check(values.equals(List.of("105","110","111")),"existing slider callback semantics changed");}
  System.out.println("Entry controls, native slider and two-corner preview: "+checks+" checks OK");
 }
}'''

